    const s = new THREE.Mesh(new THREE.PlaneGeometry(4.2, 0.9), tbSign('AN TRÀ', '#3f6e50', '#fff3c4', 52));
    s.position.set(-24, gy + 5.9, -468.2); scene.add(s);
