    twRail(fx + 0.05, -259, fx + 0.05, -279.5, 2.0, 0x2456a8, 1.2); // song sắt xanh dương
    twRail(fx + 0.05, -285.5, fx + 0.05, -290.5, 2.0, 0x2456a8, 1.2);
