    twBox(gate, 5.6, 2.1, 0.12, mat(0x1f7a3d), 0, 1.05, 0);   // cổng sắt xanh lá
    twDone(gate, fx, -282.5, 3);
    const A = twGrp(-842, -267, Math.PI / 2, 'mt_khoiA');     // khối mái tôn đỏ (dọc z)
    twBox(A, 13, 3.0, 7, mat(0xdfd3ae), 0, 1.5, 0);
