    twBox(g, 0.35, 4.0, 0.35, mat(0x2e3438), -3, 2, 9.8);
    twBox(g, 0.35, 4.0, 0.35, mat(0x2e3438), 3, 2, 9.8);
    const s = new THREE.Mesh(new THREE.PlaneGeometry(7.2, 0.8), twSign('BỘ PHẬN TIẾP NHẬN VÀ TRẢ KẾT QUẢ', '#1257a5', '#ffffff', 26));
    s.position.set(0, 3.4, 7.12); g.add(s);
