      const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.7, 0.5), bsSign('PHỐ THẾ LỮ', '#1553a0', '#ffffff', 54));
      sign.position.set(1.9, 2.3, 0); g.add(sign);
