    lnWins(g, W, FL, FH, D); lnShut(g, W, D); lnRoof(g, W, D, 0x9a958a, H + 0.24);
    if (signs && (seed % 2)) lnBoard(g, signs[seed % signs.length], '#b3241c', '#ffe9b0', W, D, 3.5, 30);
