    const sg = new THREE.Mesh(new THREE.PlaneGeometry(2.0, 1.0), v1Sign('CHO THUÊ 52+54', '#c0201a', '#ffffff', 26)); sg.position.set(4.4, 4.2, 11 / 2 + 0.06); g.add(sg);
    g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
