  // ===== HỆ THỐNG ĐƯỜNG (cell_road): tim đường VÀNG + stop bar (decal MeshBasic, merge 1 draw call) =====
  {
function rdYellowCenterline() {
  const INCLUDE_SECONDARY = false;   // true = vẽ cả 's' (nhiều phố 2 chiều hẹp không có tim vàng -> để false)
  const DASH = 4.0, GAP = 4.0;       // vạch vàng đứt 4m, hở 4m (giống ĐBP thật)
  const WIDTH = 0.45;                // RỘNG hơn vạch trắng sẵn có (0.35) -> phủ kín, hết lộ vệt trắng
  const YELLOW = 0xf2c200;
  const MED_CLEAR = 9;               // né dải phân cách vật lý (đại lộ đôi): trong 9m không vẽ tim vàng

  // khoảng cách 1 điểm tới 1 đoạn (để né MEDIANS)
  function segDist(px, pz, x1, z1, x2, z2) {
    const dx = x2 - x1, dz = z2 - z1, l2 = dx * dx + dz * dz;
    let t = l2 ? ((px - x1) * dx + (pz - z1) * dz) / l2 : 0;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(px - (x1 + dx * t), pz - (z1 + dz * t));
  }
  function nearMedian(px, pz) {
    for (const line of MEDIANS) {
      for (let i = 0; i < line.length - 1; i++) {
        if (segDist(px, pz, line[i][0], line[i][1], line[i + 1][0], line[i + 1][1]) < MED_CLEAR) return true;
      }
    }
    return false;
  }

  const geos = [];
  for (const r of ROADS_DT) {
    if (r.c !== 'p' && !(INCLUDE_SECONDARY && r.c === 's')) continue;
    for (let i = 0; i < r.pts.length - 1; i++) {
      const [x1, z1] = r.pts[i], [x2, z2] = r.pts[i + 1];
      const segLen = Math.hypot(x2 - x1, z2 - z1);
      if (segLen < DASH) continue;
      const rotY = Math.atan2(x2 - x1, z2 - z1);     // local +z -> hướng đoạn đường
      const ux = (x2 - x1) / segLen, uz = (z2 - z1) / segLen;
      for (let s = GAP; s + DASH < segLen; s += DASH + GAP) {
        const cs = s + DASH / 2;                     // tâm vạch dọc đoạn
        const mx = x1 + ux * cs, mz = z1 + uz * cs;
        if (isWater(mx, mz)) continue;
        const y = groundHeightNoDeck(mx, mz);
        if (Math.abs(y - LAND_H) > 1.0) continue;    // chỉ mặt phẳng (né dốc cầu/chỗ gãy)
        if (nearMedian(mx, mz)) continue;            // né dải phân cách vật lý
        const g = new THREE.BoxGeometry(WIDTH, 0.05, DASH);   // rộng(x) × cao × dài dọc đường(z)
        g.rotateY(rotY);
        g.translate(mx, y + 0.155, mz);
        geos.push(g);
      }
    }
  }
  if (geos.length) {
    const mesh = new THREE.Mesh(mergeGeometries(geos), new THREE.MeshBasicMaterial({ color: YELLOW }));
    geos.forEach((g) => g.dispose());
    mesh.name = 'rd_yellow_centerline';
    scene.add(mesh);
  }
}

/* ---------------------------------------------------------------------------
 *  DRAFT B — VẠCH DỪNG (stop bar) tại nút giao lớn  +  (tùy chọn) ZEBRA nâng cấp
 *  Bằng chứng pano: pano_046/152/062 có zebra + đèn tín hiệu; vạch DỪNG ngang là
 *  companion còn THIẾU (game đã có zebra ở dòng 15844-15877, CHƯA có stop bar).
 *
 *  MẶC ĐỊNH AN TOÀN: chỉ vẽ STOP BAR (thuần additive, đặt NGOÀI dải zebra sẵn có
 *  ~0.3m nên KHÔNG z-fight/không đè zebra). Muốn dùng zebra nâng cấp (rộng/sáng
 *  hơn, MeshBasic) thì bật REPLACE_EXISTING_ZEBRA=true VÀ comment khối zebra cũ
 *  (world.js dòng 15844-15877) để tránh vẽ 2 lớp chồng.
 * ------------------------------------------------------------------------- */
function rdStopBarsAndZebra() {
  const REPLACE_EXISTING_ZEBRA = false;   // true -> PHẢI tắt khối zebra cũ (15844-15877)
  const RADIUS = 1200;                     // chỉ nút giao trung tâm (giống zebra cũ dùng 1000)
  const WHITE = 0xf0eee6;

  const stopGeos = [], zebraGeos = [];
  for (const [ix, iz] of INTERSECTIONS) {
    if (ix * ix + iz * iz > RADIUS * RADIUS) continue;
    if (isWater(ix, iz)) continue;
    // đoạn đường p/s gần nhất -> hướng + nửa lòng (giống logic zebra cũ)
    let bd = 1e9, ux = 1, uz = 0, hw = 5;
    for (const r of ROADS_DT) {
      if (r.c !== 'p' && r.c !== 's') continue;
      for (let i = 0; i < r.pts.length - 1; i++) {
        const [x1, z1] = r.pts[i], [x2, z2] = r.pts[i + 1];
        const dx = x2 - x1, dz = z2 - z1, l2 = dx * dx + dz * dz; if (!l2) continue;
        let t = ((ix - x1) * dx + (iz - z1) * dz) / l2; t = Math.max(0, Math.min(1, t));
        const d = Math.hypot(ix - (x1 + dx * t), iz - (z1 + dz * t));
        if (d < bd) { bd = d; const L = Math.sqrt(l2); ux = dx / L; uz = dz / L; hw = ROAD_W[r.c] / 2; }
      }
    }
    if (bd > 6) continue;                              // nút không nằm trên p/s
    const rotY = Math.atan2(ux, uz);                  // local +z -> dọc đường; local +x -> ngang đường
    const px = -uz, pz = ux;                          // pháp tuyến (ngang đường)
    for (const dir of [-1, 1]) {                      // 2 nhánh vào nút
      // STOP BAR: đặt NGOÀI zebra cũ (zebra ở along=hw+3.2) -> along = hw+4.6 (thượng lưu),
      // chỉ phủ NỬA PHẢI theo chiều xe tới nút (VN đi phải): lệch pháp tuyến +dir*hw/2.
      const along = hw + 4.6;
      const bx = ix + ux * dir * along + px * (dir * hw / 2);
      const bz = iz + uz * dir * along + pz * (dir * hw / 2);
      const y = groundHeightNoDeck(bx, bz);
      if (Math.abs(y - LAND_H) > 0.4) continue;
      const bar = new THREE.BoxGeometry(hw, 0.05, 0.5);  // dài(x)=nửa lòng ngang đường, dày(z)=0.5 dọc đường
      bar.rotateY(rotY);
      bar.translate(bx, y + 0.14, bz);
      stopGeos.push(bar);

      if (REPLACE_EXISTING_ZEBRA) {                   // zebra nâng cấp (rộng 2.6m, sáng MeshBasic)
        const cx = ix + ux * dir * (hw + 3.2), cz = iz + uz * dir * (hw + 3.2);
        const yz = groundHeightNoDeck(cx, cz);
        if (Math.abs(yz - LAND_H) > 0.4) continue;
        for (let k = -Math.floor(hw - 1); k <= Math.floor(hw - 1); k += 1.15) {
          const sx = cx + px * k, sz = cz + pz * k;
          const strip = new THREE.BoxGeometry(0.55, 0.05, 2.6);  // dài dọc đường 2.6m
          strip.rotateY(rotY);
          strip.translate(sx, yz + 0.13, sz);
          zebraGeos.push(strip);
        }
      }
    }
  }
  if (stopGeos.length) {
    const m = new THREE.Mesh(mergeGeometries(stopGeos), new THREE.MeshBasicMaterial({ color: WHITE }));
    stopGeos.forEach((g) => g.dispose());
    m.name = 'rd_stopbars'; scene.add(m);
  }
  if (zebraGeos.length) {
    const m = new THREE.Mesh(mergeGeometries(zebraGeos), new THREE.MeshBasicMaterial({ color: WHITE }));
    zebraGeos.forEach((g) => g.dispose());
    m.name = 'rd_zebra_v2'; scene.add(m);
  }
}
    rdYellowCenterline();
    rdStopBarsAndZebra();
  }


  // ===== HỆ THỐNG CÂY (cell_tree): hàng cau vua trước công sở + phượng allée + cổ thụ xà cừ =====
  {
  const LAND_H = 2;
  const ROAD_W = { p: 13, s: 10, t: 8, r: 5.5, w: 3.5 };

  // ---- vật liệu riêng của khối (mat() có cache khi opts rỗng) ----
  const trPalmTrunkM = mat(0xc4bfb1);                                   // thân cau vua trắng-xám
  const trRingM = mat(0x9a9186);                                        // bồn gốc / vòng bảo vệ bê tông
  const trFlowerM = mat(0xd8402c, { emissive: 0x8f2416, emissiveIntensity: 0.08, flatShading: true }); // hoa phượng TRẦM, ít glow
  const trLeafA = sharedMats.leafDark;                                  // xanh trầm (chủ đạo xà cừ)
  const trLeafB = sharedMats.leafGreen2;                                // xanh sáng điểm

  // ---- bucket gom geometry theo material ----
  const B = new Map();  // material -> [BufferGeometry...]
  const push = (m, geo) => { let a = B.get(m); if (!a) B.set(m, a = []); a.push(geo); };

  // ---- helper: bake 1 geometry cơ bản với phép quay Euler(rx,0,rz) rồi tịnh tiến ----
  const _e = new THREE.Euler(), _m = new THREE.Matrix4();
  function trBake(mtl, geo, px, py, pz, rx = 0, rz = 0) {
    if (rx || rz) { _e.set(rx, 0, rz); _m.makeRotationFromEuler(_e); _m.setPosition(px, py, pz); geo.applyMatrix4(_m); }
    else geo.translate(px, py, pz);
    push(mtl, geo);
  }

  // ---- guards ----
  const trOK = (x, z) => Math.abs(groundHeightNoDeck(x, z) - LAND_H) < 0.4;   // trên đất phẳng
  function _segD(px, pz, x1, z1, x2, z2) {
    const dx = x2 - x1, dz = z2 - z1, l2 = dx * dx + dz * dz;
    let t = l2 ? ((px - x1) * dx + (pz - z1) * dz) / l2 : 0; t = Math.max(0, Math.min(1, t));
    return Math.hypot(px - (x1 + dx * t), pz - (z1 + dz * t));
  }
  // né LÒNG ĐƯỜNG mọi phố (trừ đi bộ 'w'): cách tim > nửa lòng + 0.8 m
  function trOnRoad(x, z) {
    for (const r of ROADS_DT) {
      if (r.c === 'w') continue;
      const hw = ROAD_W[r.c] / 2 + 0.8;
      for (let i = 0; i < r.pts.length - 1; i++)
        if (_segD(x, z, r.pts[i][0], r.pts[i][1], r.pts[i + 1][0], r.pts[i + 1][1]) < hw) return true;
    }
    return false;
  }
  // đoạn đường gần điểm nhất (để lấy tiếp tuyến + pháp tuyến vỉa hè)
  function trNearestSeg(px, pz) {
    let best = null;
    for (const r of ROADS_DT) {
      if (r.c === 'w') continue;
      for (let i = 0; i < r.pts.length - 1; i++) {
        const [x1, z1] = r.pts[i], [x2, z2] = r.pts[i + 1];
        const dx = x2 - x1, dz = z2 - z1, l2 = dx * dx + dz * dz;
        let t = l2 ? ((px - x1) * dx + (pz - z1) * dz) / l2 : 0; t = Math.max(0, Math.min(1, t));
        const cx = x1 + dx * t, cz = z1 + dz * t, d = Math.hypot(px - cx, pz - cz);
        if (!best || d < best.d) best = { d, cx, cz, dx, dz, c: r.c };
      }
    }
    return best;
  }

  // ---- BỒN GỐC bê tông thấp (vòng bảo vệ) quanh gốc ----
  function trBonGoc(x, z, y, r = 0.65) {
    const ring = new THREE.CylinderGeometry(r, r + 0.14, 0.34, 8); ring.translate(x, y + 0.16, z); push(trRingM, ring);
  }

  // ---- CAU VUA (royal palm): thân cao trắng-xám thẳng + chùm lá cong đều ----
  function trPalm(x, z, h = 11) {
    if (!trOK(x, z) || trOnRoad(x, z)) return false;
    const y = groundHeight(x, z);
    trBake(trPalmTrunkM, new THREE.CylinderGeometry(0.15, 0.28, h, 7), x, y + h / 2, z);
    for (let i = 0; i < 7; i++) {
      const a = i * Math.PI * 2 / 7;
      const fx = x + Math.cos(a) * 1.15, fz = z + Math.sin(a) * 1.15;
      trBake(trLeafA, new THREE.ConeGeometry(0.26, 3.2, 4), fx, y + h + 0.4, fz, Math.sin(a) * 1.2, -Math.cos(a) * 1.2);
    }
    trBonGoc(x, z, y, 0.6);
    addCollider(x, z, 0.55);
    return true;
  }

  // ---- XÀ CỪ CỔ THỤ tán CỰC RỘNG (spreader ~8-9 m) + bole cao ----
  function trBroad(x, z, h = 12, R = 8.2) {
    if (!trOK(x, z) || trOnRoad(x, z)) return false;
    const y = groundHeight(x, z);
    const boleH = h * 0.5;
    trBake(sharedMats.trunk, new THREE.CylinderGeometry(0.42, 0.68, boleH, 8), x, y + boleH / 2, z);
    // 3 cành chính toả ngang
    for (let i = 0; i < 3; i++) {
      const a = i / 3 * Math.PI * 2;
      trBake(sharedMats.trunk, new THREE.CylinderGeometry(0.16, 0.3, R * 0.5, 6),
        x + Math.cos(a) * R * 0.28, y + boleH + 0.1, z + Math.sin(a) * R * 0.28, Math.cos(a) * 1.0, -Math.sin(a) * 1.0);
    }
    // tán nhiều lớp dẹt, giao thành mái rộng
    const blobs = [[0, 0.55, 0, 1.0], [-0.6, 0.32, 0.5, 0.7], [0.6, 0.34, -0.45, 0.72], [0.15, 0.2, 0.66, 0.66], [-0.55, 0.24, -0.6, 0.64]];
    blobs.forEach(([ox, oy, oz, rf], i) => {
      const leaf = new THREE.IcosahedronGeometry(R * rf, 1); leaf.scale(1, 0.62, 1);
      leaf.translate(x + ox * R, y + boleH + oy * h, z + oz * R);
      push(i % 2 ? trLeafB : trLeafA, leaf);
    });
    trBonGoc(x, z, y, 0.95);
    addCollider(x, z, 1.3);   // chỉ chặn gốc; tán trên cao đi dưới được
    return true;
  }

  // ---- PHƯỢNG (allée) — tán xanh dẹt + vòm hoa đỏ TRẦM, nhỏ (đa số xanh) ----
  function trPhuong(x, z, h = 9, bloom = 0) {
    if (!trOK(x, z) || trOnRoad(x, z)) return false;
    const y = groundHeight(x, z);
    const boleH = h * 0.42, crownR = h * 0.42;
    trBake(sharedMats.trunk, new THREE.CylinderGeometry(0.24, 0.5, boleH, 6), x, y + boleH / 2, z);
    const green = [[0, 0.5, 0, 1.1], [-0.6, 0.05, 0.5, 0.8], [0.58, 0.08, -0.5, 0.82], [0.12, -0.06, 0.7, 0.74]];
    green.forEach(([ox, oy, oz, rf], i) => {
      const leaf = new THREE.IcosahedronGeometry(crownR * rf, 1); leaf.scale(1, 0.5, 1);
      leaf.translate(x + ox * crownR, y + boleH + oy * h + crownR * 0.5, z + oz * crownR);
      push(i % 2 ? trLeafB : trLeafA, leaf);
    });
    if (bloom > 0) {                                   // vòm hoa NHỎ, dẹt, phủ mặt trên
      const reds = [[0, 0.62, 0, 0.6], [0.4, 0.5, 0.3, 0.36], [-0.35, 0.52, -0.28, 0.34]];
      reds.forEach(([ox, oy, oz, rf]) => {
        const fl = new THREE.IcosahedronGeometry(crownR * rf, 1); fl.scale(1, 0.3, 1);
        fl.translate(x + ox * crownR, y + boleH + oy * h + crownR * 0.5, z + oz * crownR);
        push(trFlowerM, fl);
      });
    }
    trBonGoc(x, z, y, 0.6);
    addCollider(x, z, 0.85);
    return true;
  }

  // ==========================================================================
  // (1) HÀNG CAU VUA TRANG TRỌNG trước 5 công sở lớn — bám vỉa hè, dời pháp tuyến
  //     khỏi tim đường. Mỗi công sở: 1 hàng ~7 cây dọc phố chính gần nhất.
  // ==========================================================================
  const congSo = [
    ['ubnd',   LM.ubnd],     // UBND / trụ sở, [161,-823]
    ['nhnn',   LM.nhnn],     // Ngân hàng Nhà nước, [-238,-637]
    ['museum', LM.museum],   // Bảo tàng HP, [91,-492]
    ['thptnq', LM.thptnq],   // THPT Ngô Quyền, [-237,254]
    ['opera',  LM.opera],    // Nhà hát lớn (quảng trường), [0,9]
  ];
  for (const [, [lx, lz]] of congSo) {
    const seg = trNearestSeg(lx, lz); if (!seg) continue;
    const L = Math.hypot(seg.dx, seg.dz) || 1, ux = seg.dx / L, uz = seg.dz / L;   // tiếp tuyến phố
    // pháp tuyến hướng VỀ công trình (phía vỉa hè, không phải lòng đường)
    let nx = -uz, nz = ux;
    if (Math.hypot((seg.cx + nx * 3) - lx, (seg.cz + nz * 3) - lz) > Math.hypot(seg.cx - lx, seg.cz - lz)) { nx = -nx; nz = -nz; }
    const off = ROAD_W[seg.c] / 2 + 2.6;                 // ra sát mép vỉa hè
    // tâm hàng = hình chiếu công trình lên đường; trải ±3 nhịp 9 m
    const bcx = seg.cx + nx * off, bcz = seg.cz + nz * off;
    for (let k = -3; k <= 3; k++) {
      const px = bcx + ux * k * 9, pz = bcz + uz * k * 9;
      trPalm(px, pz, 10.5 + ((k + 3) % 3) * 0.9);       // cao 10.5-12.3 m, xen biến thể
    }
  }

  // ==========================================================================
  // (2) PHƯỢNG ALLÉE demo — 1 đoạn đại lộ (Bảo tàng, s) trồng 2 bên, nhịp 15 m.
  //     (Điểm nhấn "Hoa Phượng Đỏ"; đa số cây để tán xanh, ~1/3 điểm hoa.)
  // ==========================================================================
  {
    const A = [652, -450], C = [188, -455];             // đoạn phố s trước Bảo tàng (né tim đường)
    const dx = C[0] - A[0], dz = C[1] - A[1], L = Math.hypot(dx, dz), ux = dx / L, uz = dz / L;
    const nx = -uz, nz = ux;
    for (let d = 24; d < L - 12; d += 15) {
      const cx = A[0] + ux * d, cz = A[1] + uz * d;
      for (const s of [1, -1]) {
        const px = cx + nx * s * (ROAD_W.s / 2 + 3.0), pz = cz + nz * s * (ROAD_W.s / 2 + 3.0);
        const hh = ((px * 3.3 + pz * 1.9) % 1 + 1) % 1;   // hash vị trí
        trPhuong(px, pz, 8.5 + hh * 2.5, hh < 0.32 ? 1 : 0);   // ~32% điểm hoa
      }
    }
  }

  // ==========================================================================
  // (3) VÀI XÀ CỪ CỔ THỤ tán rộng — mép quảng trường / bãi cỏ công sở (né landmark,
  //     né lòng đường). Điểm chọn thủ công gần landmark nhưng lùi ra sân/bãi.
  // ==========================================================================
  for (const [x, z] of [[120, -470], [60, -470], [-210, 275], [-262, -612]]) {
    trBroad(x, z, 12.5, 8.5);
  }

  // ---- XẢ bucket → mỗi material 1 mesh (merge, dispose) ----
  for (const [mtl, geos] of B) {
    if (!geos.length) continue;
    const merged = mergeGeometries(geos.map((g) => (g.index ? g.toNonIndexed() : g)), false);
    geos.forEach((g) => g.dispose());
    const mesh = new THREE.Mesh(merged, mtl);
    mesh.castShadow = true; mesh.receiveShadow = true; mesh.name = 'tr_hpTrees';
    scene.add(mesh);
  }
  void localPt; void makeTex;  // giữ tham chiếu scope cho phần tích hợp (draft)
}


  // ===== HỆ THỐNG MẬT ĐỘ: người đi bộ + xe bổ sung (cell_dens, prefix de*) =====
  {
const CFG = {
  // Người đi bộ — thuần additive (0 hiện có). Rải p/s/t/r, cụm nhỏ + lẻ.
  PED:  { cap: 620, radius: 1250, classes: { p: 1, s: 1, t: 1, r: 1 },
          spacing: 1.35, clusterMin: 1, clusterMax: 3, clusterGap: 13,
          offBase: 2.1, offJit: 1.1, hatFrac: 0.22, startChance: 0.42, seed: 20260714 },

  // Xe máy đỗ — MẶC ĐỊNH 'r' (bổ sung parked_scooters p/s/t). Cụm 3-6 san sát, nghiêng vào vỉa hè.
  BIKE: { cap: 360, radius: 1250, classes: { r: 1 },  // mở thêm: { r:1, t:1 } hoặc {p:1,s:1,t:1,r:1}
          spacing: 0.95, clusterMin: 3, clusterMax: 6, clusterGap: 9,
          offBase: 1.2, offJit: 0.5, startChance: 0.5, seed: 20260715 },

  // Ô tô đỗ — MẶC ĐỊNH 'r' (bổ sung parked_cars p/s/t). Song song mép đường, thưa.
  CAR:  { cap: 120, radius: 1200, classes: { r: 1 },
          spacing: 5.4, clusterMin: 1, clusterMax: 3, clusterGap: 16,
          offBase: 1.35, offJit: 0.3, startChance: 0.55, seed: 20260716 },
};

function buildDensity(ctx) {
  const {
    THREE, scene, mat, mergeGeometries,
    groundHeight, groundHeightNoDeck, isWater, ROADS_DT,
    avoid,                 // optional (x,z)=>bool: né hồ/promenade/sân công trình
    debug = false,         // true: trả slots để smoke-run kiểm
  } = ctx;

  const LAND_H = 2;
  const ROAD_W = { p: 13, s: 10, t: 8, r: 5.5, w: 3.5 };   // 1:1 mét thật (như world.js)

  // ---------- guards tự chứa ----------
  const onFlat = (x, z) => Math.abs(groundHeightNoDeck(x, z) - LAND_H) < 0.4; // né cầu dốc/đồi/mép nước
  function _segD(px, pz, x1, z1, x2, z2) {
    const dx = x2 - x1, dz = z2 - z1, l2 = dx * dx + dz * dz;
    let t = l2 ? ((px - x1) * dx + (pz - z1) * dz) / l2 : 0; t = t < 0 ? 0 : t > 1 ? 1 : t;
    return Math.hypot(px - (x1 + dx * t), pz - (z1 + dz * t));
  }
  // né LÒNG ĐƯỜNG mọi phố (trừ đi bộ 'w'): cách tim MỌI đoạn > nửa lòng + 0.5 m
  function onAnyRoad(x, z) {
    for (const r of ROADS_DT) {
      if (r.c === 'w') continue;
      const hw = ROAD_W[r.c] / 2 + 0.5, pts = r.pts;
      for (let i = 0; i < pts.length - 1; i++) {
        const ax = pts[i][0], az = pts[i][1], bx = pts[i + 1][0], bz = pts[i + 1][1];
        if (Math.max(ax, bx) < x - 22 || Math.min(ax, bx) > x + 22 ||
            Math.max(az, bz) < z - 22 || Math.min(az, bz) > z + 22) continue;
        if (_segD(x, z, ax, az, bx, bz) < hw) return true;
      }
    }
    return false;
  }

  // ---------- máy rải theo VỈA HÈ (dùng chung cho cả 3 loại) ----------
  // emit(gx, gy, gz, rotY, side, rnd) — rotY = hướng đoạn đường (local +z), side ∈ {−1,+1}
  function forEachSidewalkSlot(cfg, emit) {
    let s = cfg.seed >>> 0;
    const rnd = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
    let n = 0;
    for (const r of ROADS_DT) {
      if (!cfg.classes[r.c]) continue;
      const hw = ROAD_W[r.c] / 2;
      for (let i = 0; i < r.pts.length - 1; i++) {
        const [x1, z1] = r.pts[i], [x2, z2] = r.pts[i + 1];
        const L = Math.hypot(x2 - x1, z2 - z1);
        if (L < 6) continue;
        const ux = (x2 - x1) / L, uz = (z2 - z1) / L;
        const rotY = Math.atan2(x2 - x1, z2 - z1);       // dọc đoạn
        const px = Math.cos(rotY), pz = -Math.sin(rotY); // pháp tuyến (ngang đường)
        let d = 3;
        while (d < L - 3) {
          if (rnd() > cfg.startChance) { d += cfg.clusterGap * (0.5 + rnd()); continue; }
          const side = rnd() < 0.5 ? 1 : -1;
          const count = cfg.clusterMin + ((rnd() * (cfg.clusterMax - cfg.clusterMin + 1)) | 0);
          let placed = 0;
          for (let k = 0; k < count; k++) {
            const dd = d + k * cfg.spacing;
            if (dd > L - 2) break;
            const mx = x1 + ux * dd, mz = z1 + uz * dd;
            if (mx * mx + mz * mz > cfg.radius * cfg.radius) continue;
            const off = side * (hw + cfg.offBase + rnd() * cfg.offJit);
            const gx = mx + off * px, gz = mz + off * pz;
            if (isWater(gx, gz)) continue;
            if (!onFlat(gx, gz)) continue;
            if (onAnyRoad(gx, gz)) continue;            // đảm bảo 0 vật trong lòng đường
            if (avoid && avoid(gx, gz)) continue;        // né hồ/sân (nếu ctx cấp)
            emit(gx, groundHeight(gx, gz), gz, rotY, side, rnd);
            placed++; n++;
            if (n >= cfg.cap) return n;
          }
          d += (placed ? placed * cfg.spacing : cfg.spacing) + cfg.clusterGap * (0.4 + 0.7 * rnd());
        }
      }
    }
    return n;
  }

  // ---------- tiện ích hình học ----------
  const _e = new THREE.Euler(), _m = new THREE.Matrix4();
  const bakeBox = (arr, w, h, dp, x, y, z, rx = 0) => {
    const g = new THREE.BoxGeometry(w, h, dp);
    if (rx) { g.translate(0, -h / 2, 0); _e.set(rx, 0, 0); _m.makeRotationFromEuler(_e); _m.setPosition(x, y, z); g.applyMatrix4(_m); }
    else g.translate(x, y, z);
    arr.push(g);
  };
  const disposeAll = (a) => a.forEach((g) => g.dispose && g.dispose());

  const report = { counts: {}, drawCalls: 0, slots: {} };
  const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), E = new THREE.Euler(), P = new THREE.Vector3();
  const setInst = (inst, k, x, y, z, ry, sc) => {
    E.set(0, ry, 0); Q.setFromEuler(E); P.set(x, y, z);
    M.compose(P, Q, new THREE.Vector3(sc, sc, sc)); inst.setMatrixAt(k, M);
  };

  // =====================================================================
  //  (c) NGƯỜI ĐI BỘ — khối low-poly 1 dáng mid-stride (đứng/đi), instanced
  // =====================================================================
  function dePedestrians() {
    // dáng: chân trước/sau tách, tay đối xứng -> đọc "đang đi" dù tĩnh (mẹo crowd low-poly).
    const bodyG = [], lowerG = [], headG = [], hatG = [];
    // thân + tay (áo)
    bakeBox(bodyG, 0.40, 0.52, 0.22, 0, 1.20, 0);                 // ngực
    bakeBox(bodyG, 0.13, 0.58, 0.14, 0.235, 1.46, 0, +0.26);      // tay trái (ra sau)
    bakeBox(bodyG, 0.13, 0.58, 0.14, -0.235, 1.46, 0, -0.30);     // tay phải (ra trước)
    // hông + 2 chân (quần)
    bakeBox(lowerG, 0.34, 0.20, 0.20, 0, 0.94, 0);                // hông
    bakeBox(lowerG, 0.16, 0.88, 0.17, 0.11, 0.90, 0, -0.22);      // chân trái (ra trước)
    bakeBox(lowerG, 0.16, 0.88, 0.17, -0.11, 0.90, 0, +0.24);     // chân phải (ra sau)
    // đầu + cổ (da)
    { const nk = new THREE.BoxGeometry(0.10, 0.10, 0.10); nk.translate(0, 1.52, 0); headG.push(nk); }
    { const hd = new THREE.SphereGeometry(0.125, 6, 5); hd.translate(0, 1.66, 0); headG.push(hd); } // low-poly đầu (đủ ở tầm pano)
    // nón lá (cone) — cụm con riêng, chỉ 1 phần đội
    { const h = new THREE.ConeGeometry(0.27, 0.20, 12); h.translate(0, 1.76, 0); hatG.push(h); }

    const bodyGeo = mergeGeometries(bodyG), lowerGeo = mergeGeometries(lowerG),
          headGeo = mergeGeometries(headG), hatGeo = mergeGeometries(hatG);
    disposeAll(bodyG); disposeAll(lowerG); disposeAll(headG); disposeAll(hatG);

    const shirtCols = [0xdedad2, 0x3a6ea5, 0xb5473a, 0x4a7a52, 0x6a6f76, 0xd8b24a, 0xc86a92, 0x2f3540, 0xe0e4e8, 0x8a5a3c].map((c) => new THREE.Color(c));
    const pantCols  = [0x2a2d33, 0x3a3f46, 0x24303a, 0x5a5148, 0x1f2430, 0x6b6257, 0x40454c].map((c) => new THREE.Color(c));
    const skinCols  = [0xe8b98c, 0xdca877, 0xc99060, 0xf0c79a].map((c) => new THREE.Color(c));
    const hatCol = new THREE.Color(0xd9c48a);

    const slots = [];
    forEachSidewalkSlot(CFG.PED, (x, y, z, rotY, side, rnd) => {
      // hướng: 62% dọc vỉa hè (đi tới/lui), còn lại quay linh tinh
      const face = rnd() < 0.62 ? (rotY + (rnd() < 0.5 ? 0 : Math.PI)) : rnd() * Math.PI * 2;
      const sc = 0.93 + rnd() * 0.15;                       // cao ~1.6–1.85 m
      const hat = rnd() < CFG.PED.hatFrac;
      slots.push([x, y, z, face + (rnd() - 0.5) * 0.3, sc,
                  (rnd() * shirtCols.length) | 0, (rnd() * pantCols.length) | 0, (rnd() * skinCols.length) | 0, hat]);
    });
    if (debug) report.slots.pedestrians = slots.map((s) => ({ x: s[0], z: s[2] }));
    if (!slots.length) { report.counts.pedestrians = 0; return; }

    const N = slots.length, nHat = slots.reduce((a, s) => a + (s[8] ? 1 : 0), 0);
    const bodyInst = new THREE.InstancedMesh(bodyGeo, mat(0xcccccc), N);
    const lowerInst = new THREE.InstancedMesh(lowerGeo, mat(0xcccccc), N);
    const headInst = new THREE.InstancedMesh(headGeo, mat(0xcccccc), N);
    const hatInst = nHat ? new THREE.InstancedMesh(hatGeo, mat(hatCol.getHex()), nHat) : null;
    let hi = 0;
    slots.forEach(([x, y, z, ry, sc, sci, pci, kci, hat], k) => {
      setInst(bodyInst, k, x, y, z, ry, sc); setInst(lowerInst, k, x, y, z, ry, sc); setInst(headInst, k, x, y, z, ry, sc);
      bodyInst.setColorAt(k, shirtCols[sci]); lowerInst.setColorAt(k, pantCols[pci]); headInst.setColorAt(k, skinCols[kci]);
      if (hat && hatInst) { setInst(hatInst, hi, x, y, z, ry, sc); hatInst.setColorAt(hi, hatCol); hi++; }
    });
    for (const m of [bodyInst, lowerInst, headInst, hatInst]) {
      if (!m) continue;
      m.instanceMatrix.needsUpdate = true; if (m.instanceColor) m.instanceColor.needsUpdate = true;
      m.castShadow = true; scene.add(m);
    }
    bodyInst.name = 'de_ped_body'; lowerInst.name = 'de_ped_lower'; headInst.name = 'de_ped_head';
    if (hatInst) hatInst.name = 'de_ped_hat';
    report.counts.pedestrians = N; report.counts.pedestrianHats = nHat;
    report.drawCalls += 3 + (hatInst ? 1 : 0);
  }

  // =====================================================================
  //  (a) XE MÁY ĐỖ NGHIÊNG VỈA HÈ — cụm 3-6, nghiêng mũi vào trong
  // =====================================================================
  function deParkedBikes() {
    const bodyG = [], darkG = [];
    const box = (arr, w, h, l, x, y, z) => { const g = new THREE.BoxGeometry(w, h, l); g.translate(x, y, z); arr.push(g); };
    const wheel = (z) => { const g = new THREE.CylinderGeometry(0.27, 0.27, 0.14, 10); g.rotateZ(Math.PI / 2); g.translate(0, 0.27, z); darkG.push(g); };
    wheel(-0.6); wheel(0.6);
    box(bodyG, 0.44, 0.16, 1.3, 0, 0.5, 0);       // thân/sàn
    box(bodyG, 0.4, 0.32, 0.48, 0, 0.55, 0.48);   // yếm
    box(bodyG, 0.42, 0.16, 0.58, 0, 0.74, -0.3);  // yên
    box(bodyG, 0.32, 0.28, 0.24, 0, 0.9, -0.62);  // cốp đuôi
    box(darkG, 0.1, 0.5, 0.1, 0, 0.9, 0.58);      // cổ phuộc
    box(darkG, 0.54, 0.07, 0.09, 0, 1.1, 0.6);    // ghi-đông
    const bodyGeo = mergeGeometries(bodyG), darkGeo = mergeGeometries(darkG);
    disposeAll(bodyG); disposeAll(darkG);
    const cols = [0xb23a2f, 0x2b2b2f, 0x3a5a8a, 0xd8d2c4, 0x6a6f76, 0x9c2f28, 0x24303a, 0xc7a24a].map((c) => new THREE.Color(c));

    const slots = [];
    forEachSidewalkSlot(CFG.BIKE, (x, y, z, rotY, side, rnd) => {
      // mũi quay VÀO trong (vuông góc đường), lệch nhẹ; +0.16 đứng trên mặt lát
      const nose = rotY + Math.PI / 2 * (side < 0 ? 1 : -1) + (rnd() - 0.5) * 0.25;
      slots.push([x, y + 0.16, z, nose, (rnd() * cols.length) | 0]);
    });
    if (debug) report.slots.bikes = slots.map((s) => ({ x: s[0], z: s[2] }));
    if (!slots.length) { report.counts.bikes = 0; return; }
    const bodyInst = new THREE.InstancedMesh(bodyGeo, mat(0xcccccc), slots.length);
    const darkInst = new THREE.InstancedMesh(darkGeo, mat(0x1c1c1f), slots.length);
    slots.forEach(([x, y, z, ry, ci], k) => { setInst(bodyInst, k, x, y, z, ry, 1); setInst(darkInst, k, x, y, z, ry, 1); bodyInst.setColorAt(k, cols[ci]); });
    bodyInst.instanceMatrix.needsUpdate = true; darkInst.instanceMatrix.needsUpdate = true;
    if (bodyInst.instanceColor) bodyInst.instanceColor.needsUpdate = true;
    bodyInst.castShadow = darkInst.castShadow = true;
    bodyInst.name = 'de_parked_bikes'; darkInst.name = 'de_parked_bikes_dark';
    scene.add(bodyInst); scene.add(darkInst);
    report.counts.bikes = slots.length; report.drawCalls += 2;
  }

  // =====================================================================
  //  (b) Ô TÔ ĐỖ MÉP ĐƯỜNG — song song, thưa
  // =====================================================================
  function deCurbCars() {
    const carG = [], wheelG = [];
    const box = (arr, w, h, l, x, y, z) => { const g = new THREE.BoxGeometry(w, h, l); g.translate(x, y, z); arr.push(g); };
    box(carG, 1.7, 0.5, 4.15, 0, 0.55, 0);
    box(carG, 1.48, 0.5, 2.15, 0, 1.0, -0.15);
    { const wl = (z) => { for (const sx of [0.8, -0.8]) { const g = new THREE.CylinderGeometry(0.32, 0.32, 0.2, 10); g.rotateZ(Math.PI / 2); g.translate(sx, 0.32, z); wheelG.push(g); } }; wl(1.32); wl(-1.32); }
    const carGeo = mergeGeometries(carG), wheelGeo = mergeGeometries(wheelG);
    disposeAll(carG); disposeAll(wheelG);
    const cols = [0xe6e7ea, 0xf0f0f2, 0xc2c6cc, 0x9aa0a6, 0xb5443a, 0x4a6ea0, 0x3a3f45].map((c) => new THREE.Color(c));   // tông sáng thực tế (đa số trắng/bạc — bài học bx: xe đỗ từng đen thui)

    const slots = [];
    forEachSidewalkSlot(CFG.CAR, (x, y, z, rotY, side, rnd) => {
      slots.push([x, y, z, rotY + (rnd() - 0.5) * 0.1, (rnd() * cols.length) | 0]);
    });
    if (debug) report.slots.cars = slots.map((s) => ({ x: s[0], z: s[2] }));
    if (!slots.length) { report.counts.cars = 0; return; }
    const carInst = new THREE.InstancedMesh(carGeo, mat(0xcccccc), slots.length);
    const whInst = new THREE.InstancedMesh(wheelGeo, mat(0x18181b), slots.length);
    slots.forEach(([x, y, z, ry, ci], k) => { setInst(carInst, k, x, y, z, ry, 1); setInst(whInst, k, x, y, z, ry, 1); carInst.setColorAt(k, cols[ci]); });
    carInst.instanceMatrix.needsUpdate = true; whInst.instanceMatrix.needsUpdate = true;
    if (carInst.instanceColor) carInst.instanceColor.needsUpdate = true;
    carInst.castShadow = whInst.castShadow = true;
    carInst.name = 'de_curb_cars'; whInst.name = 'de_curb_cars_wheels';
    scene.add(carInst); scene.add(whInst);
    report.counts.cars = slots.length; report.drawCalls += 2;
  }

  dePedestrians();
  deParkedBikes();
  deCurbCars();
  return report;
}

  buildDensity({ THREE, scene, mat, mergeGeometries, groundHeight, groundHeightNoDeck, isWater, ROADS_DT, avoid: (x, z) => nearFeatured(x, z) });
  }


  // ===== HỆ THỐNG BÓ VỈA (cell_curb, prefix cu*): mặt đứng bê tông mép đường p/s/t =====
  {
const CU = {
  ROAD_W:     { p: 13, s: 10, t: 8 }, // KHỚP ROAD_W world.js — chỉ p/s/t có bó vỉa (bỏ r/w)
  CURB_W:     0.18,   // bề rộng mặt bó vỉa (m); mép TRONG flush mép nhựa
  CURB_RISE:  0.14,   // mặt đứng bó vỉa cao hơn MẶT NHỰA (m) — bó vỉa thật ~12-18cm
  CURB_H:     0.30,   // chiều cao hộp (phần dưới chôn dưới vỉa hè/đất)
  ROAD_TOP_DY:0.07,   // mặt nhựa = my + 0.07 (asphalt box cao 0.14, tâm tại my)
  MY_LIFT:    0.04,   // my = (h1+h2)/2 + 0.04  (KHỚP layRoad)
  CHUNK:      30,     // chia nhỏ đoạn (KHỚP layRoad — bám dốc cầu)
  NODE_R:     8,      // bán kính CƠ BẢN né nút giao (cộng thêm half lòng đường)
  MIN_H:      0.6,    // bỏ đoạn cao độ < 0.6 (mép nước / ngập)
  MAX_DH:     6,      // bỏ đoạn gãy cao độ > 6m (nhịp cầu vòm)
  LAND_H:     2,      // KHỚP LAND_H world.js
  COLOR:      0xbdb9ad, // bê tông xám ẤM (đối chiếu pano_050/300/400/500)
};

// --- Nút giao: coord xuất hiện ở >=2 road KHÁC NHAU, hoặc là đầu/cuối 1 road ---
// (thu từ TOÀN BỘ ROADS_DT kể cả r/w để bó vỉa p/s/t biết dừng ở ngã r/w cắt vào)
function cuJunctionNodes(ROADS_DT) {
  const seen = new Map();                       // key "x,z" -> Set(roadIdx)
  const key = (x, z) => Math.round(x) + ',' + Math.round(z);
  ROADS_DT.forEach((r, ri) => {
    for (const [x, z] of r.pts) {
      const k = key(x, z);
      let s = seen.get(k); if (!s) { s = new Set(); seen.set(k, s); }
      s.add(ri);
    }
  });
  const nodes = [];
  for (const [k, set] of seen) if (set.size >= 2) { const [x, z] = k.split(',').map(Number); nodes.push([x, z]); }
  for (const r of ROADS_DT) {                    // đầu/cuối (T-end)
    const a = r.pts[0], b = r.pts[r.pts.length - 1];
    nodes.push([a[0], a[1]]); nodes.push([b[0], b[1]]);
  }
  return nodes;
}

// --- Lưới băm không gian cho nút giao (tra cứu nhanh) ---
function cuNodeGrid(nodes, cell) {
  const g = new Map();
  const key = (ix, iz) => ix + ',' + iz;
  for (const [x, z] of nodes) {
    const kk = key(Math.floor(x / cell), Math.floor(z / cell));
    let a = g.get(kk); if (!a) { a = []; g.set(kk, a); }
    a.push([x, z]);
  }
  return { g, cell };
}
function cuNearNode(grid, x, z, r) {
  const { g, cell } = grid;
  const ix = Math.floor(x / cell), iz = Math.floor(z / cell), r2 = r * r;
  for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
    const arr = g.get((ix + a) + ',' + (iz + b)); if (!arr) continue;
    for (const [nx, nz] of arr) if ((nx - x) * (nx - x) + (nz - z) * (nz - z) < r2) return true;
  }
  return false;
}

// --- Lưới lòng đường: mọi ĐOẠN p/s/t (kèm half + roadIdx) băm vào ô 8m ---
// Dùng để CHẶN bó vỉa lọt vào làn KHÁC (đại lộ đôi, đường song song sát, góc nút).
function cuLumenGrid(ROADS_DT, C) {
  const cell = 8, g = new Map();
  const put = (ix, iz, seg) => { const k = ix + ',' + iz; let a = g.get(k); if (!a) { a = []; g.set(k, a); } if (a[a.length - 1] !== seg) a.push(seg); };
  ROADS_DT.forEach((r, ri) => {
    const half = (C.ROAD_W[r.c] || 0) / 2; if (!half) return;
    for (let i = 0; i < r.pts.length - 1; i++) {
      const [ax, az] = r.pts[i], [bx, bz] = r.pts[i + 1];
      const seg = { ax, az, bx, bz, half, ri };
      const L = Math.hypot(bx - ax, bz - az), n = Math.max(1, Math.ceil(L / 2)); // bước 2m
      for (let s = 0; s <= n; s++) {
        const t = s / n, x = ax + (bx - ax) * t, z = az + (bz - az) * t;
        put(Math.floor(x / cell), Math.floor(z / cell), seg);
      }
    }
  });
  return { g, cell };
}
function cuDistPtSeg(px, pz, ax, az, bx, bz) {
  const dx = bx - ax, dz = bz - az, L2 = dx * dx + dz * dz;
  let t = L2 ? ((px - ax) * dx + (pz - az) * dz) / L2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return Math.hypot(px - (ax + dx * t), pz - (az + dz * t));
}
// true nếu điểm nằm SÂU > tol trong lòng 1 đường KHÁC (ownRi bỏ qua)
function cuInForeignLumen(grid, x, z, ownRi, tol) {
  const { g, cell } = grid, ix = Math.floor(x / cell), iz = Math.floor(z / cell);
  const done = new Set();
  for (let a = -2; a <= 2; a++) for (let b = -2; b <= 2; b++) {   // 5x5: phủ bán kính tra ~6.5m
    const arr = g.get((ix + a) + ',' + (iz + b)); if (!arr) continue;
    for (const s of arr) {
      if (s.ri === ownRi || done.has(s)) continue; done.add(s);
      if (cuDistPtSeg(x, z, s.ax, s.az, s.bx, s.bz) < s.half - tol) return true;
    }
  }
  return false;
}

// --- Generator THUẦN (không đụng THREE) — trả danh sách hộp bó vỉa để build/kiểm ---
// Mỗi phần tử: { x,y,z (tâm hộp), rotY,rotX, len,w,h, innerFace (khoảng cách mép
//   trong tới tim đường — để smoke-run kiểm intrusion), cx,cz (tim đoạn) }
function cuCurbSegments(deps) {
  const { ROADS_DT, groundHeightNoDeck, isWater } = deps;
  const C = deps.CU || CU;
  const grid = cuNodeGrid(cuJunctionNodes(ROADS_DT), C.NODE_R);
  const lumen = cuLumenGrid(ROADS_DT, C);
  const out = [];
  for (let ri = 0; ri < ROADS_DT.length; ri++) {
    const r = ROADS_DT[ri];
    const wRoad = C.ROAD_W[r.c]; if (!wRoad) continue;     // chỉ p/s/t
    const half = wRoad / 2;
    for (let i = 0; i < r.pts.length - 1; i++) {
      const [x1, z1] = r.pts[i], [x2, z2] = r.pts[i + 1];
      const segLen = Math.hypot(x2 - x1, z2 - z1);
      if (segLen < 1) continue;
      const rotY = Math.atan2(x2 - x1, z2 - z1);
      const nCh = Math.max(1, Math.ceil(segLen / C.CHUNK));
      for (let c = 0; c < nCh; c++) {
        const t1 = c / nCh, t2 = (c + 1) / nCh;
        const cx1 = x1 + (x2 - x1) * t1, cz1 = z1 + (z2 - z1) * t1;
        const cx2 = x1 + (x2 - x1) * t2, cz2 = z1 + (z2 - z1) * t2;
        const mx = (cx1 + cx2) / 2, mz = (cz1 + cz2) / 2;
        const len = segLen / nCh;
        const g1 = groundHeightNoDeck(cx1, cz1), g2 = groundHeightNoDeck(cx2, cz2);
        const h1 = Math.max(g1, C.LAND_H), h2 = Math.max(g2, C.LAND_H);
        if (Math.abs(h1 - h2) > C.MAX_DH) continue;                       // gãy / cầu
        if (isWater(mx, mz) || isWater(cx1, cz1) || isWater(cx2, cz2)) continue; // nước
        if (Math.min(g1, g2) < C.MIN_H) continue;                         // mép nước
        if (cuNearNode(grid, mx, mz, C.NODE_R + half)) continue;          // nút giao
        const my = (h1 + h2) / 2 + C.MY_LIFT;
        const rotX = Math.atan2(h1 - h2, len);
        const px = Math.cos(rotY), pz = -Math.sin(rotY);
        const centerY = my + C.ROAD_TOP_DY + C.CURB_RISE - C.CURB_H / 2;  // top = mặt nhựa + RISE
        for (const side of [-1, 1]) {
          const off = side * (half + C.CURB_W / 2);                       // mép trong tại đúng `half`
          const cxp = mx + off * px, czp = mz + off * pz;                 // TÂM hộp bó vỉa
          const iex = mx + side * half * px, iez = mz + side * half * pz; // MÉP TRONG bó vỉa
          if (isWater(cxp, czp) || isWater(iex, iez)) continue;           // né nước theo TỪNG bên
          if (cuInForeignLumen(lumen, iex, iez, ri, 0.3)) continue;       // né lọt làn khác
          out.push({
            x: cxp, y: centerY, z: czp,
            rotY, rotX, len, w: C.CURB_W, h: C.CURB_H,
            innerFace: half, cx: mx, cz: mz,
          });
        }
      }
    }
  }
  return out;
}

// --- Builder THREE: gộp toàn bộ hộp bó vỉa thành 1 mesh (1 draw call) ---
function cuBuildCurbs(deps) {
  const { THREE, scene, mat, mergeGeometries } = deps;
  const C = deps.CU || CU;
  const segs = cuCurbSegments(deps);
  if (!segs.length) return null;
  const geos = [];
  const m4 = new THREE.Matrix4(), q4 = new THREE.Quaternion(), e4 = new THREE.Euler(), s4 = new THREE.Vector3(1, 1, 1);
  for (const s of segs) {
    const g = new THREE.BoxGeometry(s.w, s.h, s.len + 0.4);   // +0.4 chồng mép tránh hở
    e4.set(s.rotX, s.rotY, 0); q4.setFromEuler(e4);
    m4.compose(new THREE.Vector3(s.x, s.y, s.z), q4, s4);
    g.applyMatrix4(m4);
    geos.push(g);
  }
  const merged = mergeGeometries(geos);
  geos.forEach((g) => g.dispose());
  const mesh = new THREE.Mesh(merged, mat(C.COLOR));
  mesh.name = 'street_curbs'; mesh.receiveShadow = true; scene.add(mesh);
  return mesh;
}

  cuBuildCurbs({ THREE, scene, mat, mergeGeometries, groundHeightNoDeck, isWater, ROADS_DT });
  }


  // ===== FIX t8 (cell_struct): CỤM NHÀ KHO CẢNG mở rộng (block_infill dừng ở z=-900) =====
  {
    const bcOK = (x, z) => !isWater(x, z) && groundHeight(x, z) > 1.4;
    const roofM = [mat(0x9c6b4a), mat(0x8f8a5f), mat(0x8a7a5a)];
    const wallM = mat(0x8c8a7e);
    const CLV = [-118, -927], CLV_R = 160;
    const near = (x, z, cx, cz, r) => ((x - cx) ** 2 + (z - cz) ** 2) < r * r;
    const rows = [
      [-938, [[470, 100], [590, 100], [710, 120], [840, 90]]],
      [-905, [[60, 110], [500, 110], [640, 110], [790, 130]]],
      [-872, [[120, 90], [560, 120], [720, 110]]],
    ];
    let wi = 100;
    for (const [zc, units] of rows) for (const [xc, W] of units) {
      if (!bcOK(xc, zc)) continue;
      if (near(xc, zc, CLV[0], CLV[1], CLV_R)) continue;
      if (xc > 120 && xc < 420 && zc < -890) continue;
      const g = new THREE.Group();
      g.position.set(xc, groundHeight(xc, zc), zc);
      const D = 22, H = 6.0;
      const body = new THREE.Mesh(new THREE.BoxGeometry(W, H, D), wallM);
      body.position.y = H / 2; g.add(body);
      for (const sgn of [-1, 1]) {
        const rf = new THREE.Mesh(new THREE.BoxGeometry(W + 1, 0.18, D * 0.58), roofM[wi % 3]);
        rf.position.set(0, H + 0.95, sgn * D * 0.22); rf.rotation.x = -sgn * 0.32; g.add(rf);
      }
      g.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
      g.name = 'port_kho_' + wi; scene.add(g);
      for (const lx of [-W / 3, 0, W / 3]) addCollider(xc + lx, zc, D / 2 + 1);
      FEATURED_CLEAR.push([xc, zc, W / 2 + 8]);
      wi++;
    }
  }


  // ===== GRIND BỀ MẶT sb ĐÔNG-NAM (8 block Cầu Đất Nam) =====
// ============================================================================
// CELL_SB — CẦU ĐẤT NAM (đoạn số 158–202, gần Ga) + nút Cầu Đất × Lê Lợi
//   Dải TRỐNG THẬT: pano_371(317,487) 158 / pano_370(347,513) 65-182 /
//   pano_369(379,539) 181 / pano_373(387,546) 187 nút Lê Lợi.
//   Kiểm chứng: nf tới featured gần nhất 68–112m (ln lot LN4 chỉ làm đoạn BẮC
//   z<460: 466/179/178/177/372 — đoạn NAM z>485 còn trống hoàn toàn).
//   Cầu Đất = road 's' half=5, u=(-0.754,-0.657) (chạy TB↔ĐN).
//   MỌI khối: pano=tim đường → dời pháp tuyến (half 5 + 2.3 vỉa + D/2 + yard);
//   facade cách pano-camera ~9.5m (>6m, đạt ≥9m), 0 lấn lòng đường (smoke verify).
//   Scope buildWorld: THREE, mat, makeTex, sharedMats, addCollider,
//   FEATURED_CLEAR, groundHeight, groundHeightNoDeck, isWater, localPt,
//   mergeGeometries, scene. Helper TỰ CHỨA prefix sb*. (LAND_H≡2.0 hardcode.)
// ============================================================================
{
  // ---------- HELPERS TỰ CHỨA (sb*) ----------
  const sbSign = (txt, bg, fg = '#ffffff', px = 42) => new THREE.MeshLambertMaterial({
    map: makeTex(512, 96, (g, w, h) => {
      g.fillStyle = bg; g.fillRect(0, 0, w, h);
      g.fillStyle = fg; g.font = `bold ${px}px system-ui, sans-serif`;
      g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(txt, w / 2, h / 2 + 2, w - 24);
    }),
  });
  const sbFacade = (baseCss, winCss, cols, rows, arch = false) => new THREE.MeshLambertMaterial({
    map: makeTex(256, 256, (g, w, h) => {
      g.fillStyle = baseCss; g.fillRect(0, 0, w, h);
      const mx = w * 0.11, my = h * 0.12, cw = (w - mx * 2) / cols, ch = (h - my * 2) / rows;
      for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
        g.fillStyle = winCss;
        if (arch && r === rows - 1) {
          g.fillRect(mx + c * cw + cw * 0.16, my + r * ch + ch * 0.22, cw * 0.68, ch * 0.6);
          g.beginPath(); g.arc(mx + c * cw + cw * 0.5, my + r * ch + ch * 0.22, cw * 0.34, Math.PI, 0); g.fill();
        } else g.fillRect(mx + c * cw + cw * 0.16, my + r * ch + ch * 0.16, cw * 0.68, ch * 0.66);
      }
    }),
  });
  const sbOK = (x, z) => Math.abs(groundHeightNoDeck(x, z) - 2.0) < 0.5 && !isWater(x, z);

  /*SB_DATA_START*/ // vùng THUẦN TOÁN (không phụ thuộc three) — smoke verify eval khối này
  const CDU = [-0.754, -0.657];   // vector tim đường Cầu Đất (đơn vị)
  const HALF = 5;                 // nửa lòng đường 's'
  // pano=tim đường → tâm khối lệch pháp tuyến (HALF + 2.3 vỉa + D/2 + yard)
  const sbAt = (cx, cz, sd, along, D, yard) => {
    const ux = CDU[0], uz = CDU[1], nx = -uz, nz = ux;
    const oc = HALF + 2.3 + D / 2 + yard;
    const bx = cx + ux * along + nx * sd * oc;
    const bz = cz + uz * along + nz * sd * oc;
    const ry = Math.atan2(-nx * sd, -nz * sd);   // mặt tiền (local +Z) quay về phía pano
    return [bx, bz, ry];
  };
  const SB_SPEC = [
    // --- pano_371 (317,487) — Cầu Đất số 158 ---
    { p: [316.5, 487.0], sd: 1, along: 0, W: 16, D: 11, FL: 3, yard: 2.2, type: 'brick',
      wall: '#9e3b30', win: '#efe0c8', roof: '#7a4535', name: 'sb_371_gachphap',
      board: ['CẦU ĐẤT 158', '#7a2b22', '#f0e0c0'] },
    { p: [316.5, 487.0], sd: -1, along: 3.5, W: 22, D: 9, FL: 3, yard: 2.2, type: 'shop',
      wall: '#efe6d2', win: '#7a8793', roof: '#9a958a', name: 'sb_371_coop',
      board: ['CO.OP — SIÊU THỊ MINI • THÁI', '#0f6a38', '#ffffff', 34] },
    // --- pano_370 (347,513) — Cầu Đất số 65-182 ---
    { p: [347.3, 513.3], sd: 1, along: 0, W: 12, D: 9, FL: 2, yard: 2.2, type: 'french',
      wall: '#e6cf86', win: '#5f6a70', shut: '#3f6a52', roof: '#9a958a', name: 'sb_370_coanh',
      board: ['ĂN VẶT CÔ ÁNH', '#e0508e', '#ffffff'] },
    { p: [347.3, 513.3], sd: -1, along: 2.0, W: 8, D: 8, FL: 2, yard: 2.2, type: 'shop',
      wall: '#242424', win: '#c9a24a', roof: '#3a3a3a', name: 'sb_370_phuonglinh',
      board: ['PHƯƠNG LINH FASHION — MAY ĐO', '#141414', '#e8c85a', 32] },
    // --- pano_369 (379,539) — Cầu Đất số 181 (Bánh đa cua Bà Cụ) ---
    { p: [378.9, 538.5], sd: 1, along: 0, W: 12, D: 9, FL: 2, yard: 2.2, type: 'french',
      wall: '#5f6b4a', win: '#4a5540', shut: '#3a4a34', roof: '#7a4a34', name: 'sb_369_bacua',
      board: ['BÀ CỤ — BÁNH ĐA CUA HẢI PHÒNG', '#a01c1c', '#ffe08a', 30], lantern: true },
    { p: [378.9, 538.5], sd: -1, along: 1.0, W: 8, D: 8, FL: 2, yard: 2.2, type: 'shop',
      wall: '#2b2b2b', win: '#c9a24a', roof: '#3a3a3a', name: 'sb_369_euro',
      board: ['EURO FASHION SHOP', '#1a1a1a', '#e8c85a'] },
    // --- pano_373 (387,546) — nút Cầu Đất × Lê Lợi (số 187-191, phố vàng bạc) ---
    // (369 & 373 chỉ cách ~10m → xếp liền dải: Ngọc Sơn ĐN của Bà Cụ (sd+1),
    //  Kim Ngân ĐN của Euro (sd-1); along tính để 0 chồng lấn)
    { p: [386.7, 545.5], sd: 1, along: -4.0, W: 11, D: 9, FL: 2, yard: 2.2, type: 'gold',
      wall: '#e6e04a', win: '#4a5560', roof: '#b0aa9a', name: 'sb_373_ngocson',
      board: ['NGỌC SƠN 68 — KIOSK CHỢ TAM BẠC', '#c1201a', '#ffe08a', 30] },
    { p: [386.7, 545.5], sd: -1, along: 0.0, W: 6, D: 9, FL: 4, yard: 2.2, type: 'tower',
      wall: '#26282c', win: '#54718a', roof: '#b0aa9a', name: 'sb_373_kimngan',
      vsign: ['VÀNG KIM NGÂN 191', '#0b0b0b', '#ff3b30'],
      board: ['191 CẦU ĐẤT', '#0b0b0b', '#ffcc33', 34] },
  ];
  /*SB_DATA_END*/

  // ---------- RENDER HELPERS (three) ----------
  const sbMk = (bx, bz, ry) => { const g = new THREE.Group(); g.position.set(bx, groundHeight(bx, bz), bz); g.rotation.y = ry; return g; };
  const sbBody = (g, W, H, D, m) => { const b = new THREE.Mesh(new THREE.BoxGeometry(W, H, D), m); b.position.y = H / 2; g.add(b); return b; };
  const sbFlatRoof = (g, W, D, hex, y) => { const r = new THREE.Mesh(new THREE.BoxGeometry(W + 0.6, 0.5, D + 0.6), mat(hex)); r.position.y = y; g.add(r); };
  const sbTiledRoof = (g, W, D, hex, y) => {
    const ge = [];
    const a = new THREE.BoxGeometry(W + 0.7, 0.32, D * 0.62); a.rotateX(0.42); a.translate(0, y, D * 0.2); ge.push(a);
    const b = new THREE.BoxGeometry(W + 0.7, 0.32, D * 0.62); b.rotateX(-0.42); b.translate(0, y, -D * 0.2); ge.push(b);
    g.add(new THREE.Mesh(mergeGeometries(ge), mat(hex)));
  };
  const sbBoard = (g, spec, D, y) => { if (!spec) return; const s = new THREE.Mesh(new THREE.PlaneGeometry(Math.max((spec[3] ? 3.2 : 3.4), 3), 1.0), sbSign(spec[0], spec[1], spec[2] || '#fff', spec[3] || 42)); s.position.set(0, y, D / 2 + 0.09); g.add(s); };
  const sbBalcony = (g, W, D, y) => {
    const slab = new THREE.Mesh(new THREE.BoxGeometry(W * 0.94, 0.16, 1.1), mat(0xcfc8b6)); slab.position.set(0, y, D / 2 + 0.5); g.add(slab);
    const rail = new THREE.Mesh(new THREE.BoxGeometry(W * 0.94, 0.7, 0.08), mat(0x40474d)); rail.position.set(0, y + 0.42, D / 2 + 1.02); g.add(rail);
  };
  const sbShutters = (g, W, D, FL, hex) => {
    for (let f = 0; f < FL; f++) for (const sx of [-W * 0.26, W * 0.26]) {
      const sh = new THREE.Mesh(new THREE.BoxGeometry(W * 0.2, 1.6, 0.08), mat(hex));
      sh.position.set(sx, f * 3.3 + 2.1, D / 2 + 0.05); g.add(sh);
    }
  };
  const sbGlass = (g, W, D) => { const gl = new THREE.Mesh(new THREE.BoxGeometry(W * 0.88, 2.7, 0.12), sharedMats.window); gl.position.set(0, 1.5, D / 2 + 0.06); g.add(gl); };
  const sbVSign = (g, spec, W, D, H) => {
    if (!spec) return;
    const s = new THREE.Mesh(new THREE.PlaneGeometry(1.1, H * 0.7), sbSign(spec[0], spec[1], spec[2] || '#fff', 30));
    s.position.set(W / 2 + 0.08, H * 0.55, D / 2 - 0.6); s.rotation.y = -Math.PI / 2; g.add(s);
  };
  const sbLantern = (g, W, D) => {
    for (let i = -1; i <= 1; i++) { const l = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 6), mat(0xd23b2a, { emissive: 0x7a1c14, emissiveIntensity: 0.25 })); l.position.set(i * W * 0.3, 2.9, D / 2 + 0.7); g.add(l); }
  };
  const sbFin = (g, name, bx, bz, colR, clrR) => {
    g.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    g.name = name; scene.add(g);
    if (colR > 0) addCollider(bx, bz, colR);
    FEATURED_CLEAR.push([bx, bz, clrR]);
  };

  // ---------- BUILD ----------
  for (const s of SB_SPEC) {
    const [bx, bz, ry] = sbAt(s.p[0], s.p[1], s.sd, s.along, s.D, s.yard);
    if (!sbOK(bx, bz)) continue;
    const H = s.FL * 3.3, g = sbMk(bx, bz, ry);
    if (s.type === 'french') {
      sbBody(g, s.W, H, s.D, sbFacade(s.wall, s.win, Math.max(3, Math.round(s.W / 3)), s.FL));
      sbShutters(g, s.W, s.D, s.FL, s.shut || '#3f6a52');
      sbBalcony(g, s.W, s.D, 3.4);
      sbTiledRoof(g, s.W, s.D, s.roof, H + 0.3);
      sbBoard(g, s.board, s.D, H - 0.9);
      if (s.lantern) sbLantern(g, s.W, s.D);
    } else if (s.type === 'brick') {
      sbBody(g, s.W, H, s.D, sbFacade(s.wall, s.win, Math.max(4, Math.round(s.W / 3)), s.FL, true));
      sbTiledRoof(g, s.W, s.D, s.roof, H + 0.35);
      // cầu thang bê tông lan can đỏ-trắng trước mặt
      const stair = new THREE.Mesh(new THREE.BoxGeometry(s.W * 0.4, 1.0, 1.6), mat(0xcabfa8)); stair.position.set(0, 0.5, s.D / 2 + 0.9); g.add(stair);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(s.W * 0.4, 0.7, 0.08), mat(0xb03a30)); rail.position.set(0, 1.3, s.D / 2 + 1.6); g.add(rail);
      sbBoard(g, s.board, s.D, H - 0.8);
    } else if (s.type === 'gold') {
      sbBody(g, s.W, H, s.D, mat(parseInt(s.wall.slice(1), 16)));
      sbGlass(g, s.W, s.D);
      sbFlatRoof(g, s.W, s.D, s.roof, H + 0.3);
      sbBoard(g, s.board, s.D, H - 0.7);
    } else if (s.type === 'tower') {
      sbBody(g, s.W, H, s.D, sbFacade(s.wall, s.win, Math.max(2, Math.round(s.W / 3)), s.FL));
      for (let f = 0; f < s.FL; f++) { const band = new THREE.Mesh(new THREE.BoxGeometry(s.W + 0.12, 1.2, s.D + 0.12), sharedMats.window); band.position.y = f * 3.3 + 3.3 * 0.62; g.add(band); }
      sbFlatRoof(g, s.W, s.D, s.roof, H + 0.28);
      sbVSign(g, s.vsign, s.W, s.D, H);
      sbBoard(g, s.board, s.D, H - 0.7);
    } else { // shop
      sbBody(g, s.W, H, s.D, sbFacade(s.wall, s.win, Math.max(2, Math.round(s.W / 3.5)), s.FL));
      sbFlatRoof(g, s.W, s.D, s.roof, H + 0.28);
      sbBoard(g, s.board, s.D, H - 0.8);
    }
    sbFin(g, s.name, bx, bz, Math.max(s.W, s.D) * 0.5, Math.max(s.W, s.D) / 2 + 6);
  }
}


  // ===== GRIND BỀ MẶT sa GIỮA-TÂY (12 block) =====
/* =====================================================================
   CELL_SA — MẶT TRẬN GIỮA-TÂY (lõi Hồng Bàng / Lê Chân): 12 DÃY NHÀ CHÍNH
   đích danh cho các phố GIỮA-TÂY còn TRỐNG THẬT trong khung
   x∈[-600,-100], z∈[-450,350]:
     Kỳ Đồng (TT Y tế Q.Hồng Bàng) · Phan Bội Châu (ẩm thực/cà phê) ·
     Lãn Ông (PG Bank) · Lý Thường Kiệt (shophouse san sát) ·
     Mê Linh (thời trang) · Quang Trung (chăn ga/đồ chơi) ·
     Nguyễn Đức Cảnh ven hồ (SIXDO/Mixue/VietABank).

   MỤC TIÊU (minh hoạ, KHÔNG photoreal): nhà CHÍNH đúng KHỐI (vị trí/tầng/
   bề rộng) + đúng MÀU + đúng LOẠI (shophouse liền kề · công sở khuôn viên ·
   mặt kính). Nguồn màu/tầng: audit/audit_done.json; tọa độ pano tim đường:
   tools/pano_loop/capture_list.json.

   CHỌN Ô: đã grep world.js FEATURED_CLEAR + đọc block đã tích hợp
   (CELL_TAY hb* / CELL_S1 / CELL_S2 s2* / CELL_TAYSONG ts* / CELL_LOINAM ln* /
   CELL_BAC bc* / CELL_BACSONG bs*) + prox-scan: CHỈ giữ pano có công trình
   đích-danh gần nhất ≥40m (12 pano: 498/433/432/434/131/132/137/497/262/003/033).

   HÌNH HỌC (khớp bài học pano-loop): pano = TIM ĐƯỜNG (xe Google). Dời theo
   PHÁP TUYẾN một khoảng `off = front + D/2`, với `front` = khoảng cách MẶT TIỀN
   tới tim. `front` đã chọn RIÊNG mỗi dãy để mặt tiền cách CAMERA PANO THẬT ≥6.6m
   (camera lệch tim tới ~3m ở phố hẹp → tính lean, xem cell_sa/lean.mjs), tránh
   lỗi #1 "camera bị nhà che kín". Smoke-run: roadClr≥2.6m, camMin≥6.6m, 0 nước.

   VỊ TRÍ DÁN: js/world.js — trong buildWorld, CÙNG CHỖ CELL_S2/CELL_TAYSONG
   (sau khối "CÔNG TRÌNH ĐẶC TRƯNG" + các cell shophouse, TRƯỚC vòng OSM/
   block_infill). Helper sa* + SA_ROWS + vòng đặt khai báo Ở CẤP buildWorld
   (giống s2* và ts*), KHÔNG bọc {} ngoài cùng. FEATURED_CLEAR.push mỗi lô → đuổi
   nhà OSM/infill generic khỏi mặt tiền đích-danh.

   SCOPE có sẵn (KHÔNG khai báo lại): THREE, mat, makeTex, sharedMats,
   addCollider, FEATURED_CLEAR, groundHeight, groundHeightNoDeck, isWater,
   localPt, scene, mergeGeometries.
   ===================================================================== */

// ============ HELPER TỰ CHỨA sa* (khai báo 1 LẦN, cấp buildWorld) ============
const _saFC = new Map();                 // cache material mặt tiền (≤ ~24 material)
// texture nhà ống: nền tường + hàng cửa sổ mỗi tầng + cửa cuốn/kính trệt + băng biển
const saFacade = (wallCss, bandCss, floors, bays) => {
  const key = wallCss + '|' + bandCss + '|' + floors + '|' + bays;
  let m = _saFC.get(key);
  if (m) return m;
  const FPX = 128, W = bays * 96;
  const tex = makeTex(W, FPX * floors, (g, w, h) => {
    g.fillStyle = wallCss; g.fillRect(0, 0, w, h);
    const bw = w / bays;
    for (let f = 0; f < floors; f++) {
      const y0 = h - (f + 1) * FPX;                     // f=0 = tầng trệt (dưới cùng)
      for (let b = 0; b < bays; b++) {
        const x0 = b * bw;
        if (f === 0) {                                  // trệt: cửa cuốn tối + băng biển
          g.fillStyle = '#2a2d33'; g.fillRect(x0 + bw * 0.08, y0 + FPX * 0.30, bw * 0.84, FPX * 0.56);
          g.fillStyle = bandCss;   g.fillRect(x0, y0 + FPX * 0.06, bw, FPX * 0.20);
        } else {                                        // trên: khung cửa trắng + kính xanh xám
          g.fillStyle = '#f4f1e8'; g.fillRect(x0 + bw * 0.14, y0 + FPX * 0.16, bw * 0.72, FPX * 0.62);
          g.fillStyle = '#4a6b82'; g.fillRect(x0 + bw * 0.20, y0 + FPX * 0.22, bw * 0.60, FPX * 0.50);
        }
      }
    }
  });
  tex.wrapS = THREE.RepeatWrapping; tex.repeat.set(bays, 1);
  m = new THREE.MeshLambertMaterial({ map: tex });
  _saFC.set(key, m); return m;
};

// biển hiệu chữ (MeshBasic — không ăn nắng, đọc rõ như biển thật)
const saSign = (txt, bg, fg, size) => new THREE.MeshBasicMaterial({
  side: THREE.DoubleSide,
  map: makeTex(512, 128, (g, w, h) => {
    g.fillStyle = bg || '#c01822'; g.fillRect(0, 0, w, h);
    g.fillStyle = fg || '#ffffff'; g.font = 'bold ' + (size || 44) + 'px system-ui, sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(txt, w / 2, h / 2 + 4, w - 22);
  }),
});

// DÃY NHÀ CHÍNH: cx,cz = TIM ĐƯỜNG; (nx,nz) = pháp tuyến ĐƠN VỊ (+n);
// side=±1 chọn bờ; front = khoảng cách mặt tiền→tim; D = độ sâu nhà;
// lots = [{w, fl, wall, band, sign, sfg, ssz, kind:'gov'|'glass'|undefined}]
const saRow = (cx, cz, nx, nz, side, front, D, lots, name) => {
  const off = front + D / 2;
  const gx = cx + side * nx * off, gz = cz + side * nz * off;
  if (isWater(gx, gz)) return null;                     // né lòng sông/hồ (nhà lơ lửng)
  const th = Math.atan2(-side * nx, -side * nz);        // mặt tiền (local +Z) quay về tim
  const g = new THREE.Group();
  g.position.set(gx, groundHeight(gx, gz), gz); g.rotation.y = th;
  const total = lots.reduce((s, l) => s + l.w, 0);
  let run = -total / 2;
  for (const L of lots) {
    const lxc = run + L.w / 2, FL = L.fl || 3, H = FL * 3.3;
    if (L.kind === 'gov') {                             // CÔNG SỞ / KHUÔN VIÊN: hộp kem + băng biển rộng + bệ
      const body = new THREE.Mesh(new THREE.BoxGeometry(L.w, H, D), mat(L.wall || 0xe7dcc0));
      body.position.set(lxc, H / 2, 0); g.add(body);
      for (let f = 1; f < FL; f++) {                    // hàng cửa sổ băng ngang
        const win = new THREE.Mesh(new THREE.BoxGeometry(L.w * 0.9, 1.2, 0.1), sharedMats.window);
        win.position.set(lxc, f * 3.3 + 1.5, D / 2 + 0.05); g.add(win);
      }
      const plinth = new THREE.Mesh(new THREE.BoxGeometry(L.w + 0.6, 1.0, D + 0.6), mat(0xbdb6a4));
      plinth.position.set(lxc, 0.5, 0); g.add(plinth);
    } else if (L.kind === 'glass') {                    // MẶT KÍNH (cà phê / showroom / thời trang cao cấp)
      const body = new THREE.Mesh(new THREE.BoxGeometry(L.w, H, D), mat(L.wall || 0x2a2d33));
      body.position.set(lxc, H / 2, 0); g.add(body);
      const gl = new THREE.Mesh(new THREE.BoxGeometry(L.w * 0.92, H - 1.0, 0.16), sharedMats.window);
      gl.position.set(lxc, (H - 1.0) / 2 + 0.3, D / 2 + 0.05); g.add(gl);
    } else {                                            // SHOPHOUSE nhà ống: facade texture
      const bays = Math.max(1, Math.round(L.w / 4));
      const body = new THREE.Mesh(new THREE.BoxGeometry(L.w, H, D),
        saFacade(L.wall || '#ecdcb0', L.band || '#c01822', FL, bays));
      body.position.set(lxc, H / 2, 0); g.add(body);
      const glass = new THREE.Mesh(new THREE.BoxGeometry(L.w * 0.84, 2.3, 0.1), sharedMats.window);
      glass.position.set(lxc, 1.35, D / 2 + 0.05); g.add(glass);
    }
    // mái phẳng bê tông mảnh (đồng nhất khối phố)
    const roof = new THREE.Mesh(new THREE.BoxGeometry(L.w + 0.3, 0.4, D + 0.3), mat(0xb8b2a2));
    roof.position.set(lxc, H + 0.2, 0); g.add(roof);
    if (L.sign) {                                       // băng biển hiệu tầng trệt
      const s = new THREE.Mesh(new THREE.PlaneGeometry(Math.min(L.w * 0.94, 13), 1.15),
        saSign(L.sign, L.band, L.sfg, L.ssz));
      s.position.set(lxc, (L.kind === 'gov' ? 3.0 : 3.2), D / 2 + 0.08); g.add(s);
    }
    const [wx, wz] = localPt(gx, gz, lxc, 0, th);
    addCollider(wx, wz, Math.max(2.5, Math.min(L.w, D) / 2));
    FEATURED_CLEAR.push([wx, wz, Math.max(L.w, D) / 2 + 6]);   // đuổi OSM/infill khỏi mặt tiền
    run += L.w;
  }
  g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
  g.name = name; scene.add(g);
  return g;
};

// ============ DỮ LIỆU 12 DÃY (front đã chọn để mặt tiền cách camera pano ≥6.6m) ============
