    const l = new THREE.Mesh(new THREE.BoxGeometry(13, H, D), mat(0x2f7d3f)); l.position.set(-3.2, H / 2, 0); g.add(l);
    const r = new THREE.Mesh(new THREE.BoxGeometry(6.6, H, D), mat(0x2b2c30)); r.position.set(6.8, H / 2, 0); g.add(r);
